.chapter-scope {
  --ink: #1a2b4a;
  --muted: #5c6b7f;
  --accent: #007acc;
  --warm: #b85c38;
  --paper: #f9f7f1;
  --line: #d1c7b7;

  font-family: 'Source Serif Pro', serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
  font-size: 16px;
}

.chapter-scope h1 {
  font-size: 2.2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.5rem;
}

.chapter-scope h2 {
  font-size: 1.5rem;
  margin-top: 2rem;
  color: var(--accent);
}

.chapter-scope h3 {
  font-size: 1.2rem;
  margin-top: 1.5rem;
  color: var(--ink);
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 70ch;
  margin-bottom: 2rem;
}

.manuscript-flow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

@media (max-width: 768px) {
  .manuscript-flow {
    grid-template-columns: 1fr;
  }
}

.source-list {
  list-style: none;
  padding-left: 0;
}

.source-list li {
  margin-bottom: 1rem;
  padding-left: 1rem;
  border-left: 3px solid var(--accent);
}

.formula-block {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1rem;
  text-align: center;
  font-family: 'Times New Roman', serif;
  font-size: 1.2rem;
  margin: 1.5rem 0;
  box-shadow: 2px 2px 0 rgba(0,0,0,0.05);
}

.interactive-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1.5rem;
  box-shadow: 4px 4px 0 rgba(26, 43, 74, 0.1);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.card-header h3 {
  margin: 0;
  font-size: 1.1rem;
}

.controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.controls label {
  font-size: 0.9rem;
  font-weight: bold;
}

.controls input[type="range"] {
  width: 120px;
  accent-color: var(--accent);
}

.btn-text {
  background: none;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.2rem 0.6rem;
  font-size: 0.8rem;
  cursor: pointer;
  border-radius: 2px;
}

.btn-text:hover {
  background: var(--muted);
  color: #fff;
}

.chart-container {
  position: relative;
  width: 100%;
  height: 300px;
  margin-bottom: 1rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  border-top: 1px solid var(--line);
  padding-top: 1rem;
}

.stat-item {
  display: flex;
  flex-direction: column;
}

.stat-item .label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-item .value {
  font-size: 1.4rem;
  font-weight: bold;
  color: var(--ink);
  font-family: monospace;
}

.stat-item.highlight .value {
  color: var(--accent);
}

.caption {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.5rem;
  font-style: italic;
}

.limitations-section {
  margin-top: 3rem;
  padding: 1.5rem;
  background: rgba(184, 92, 56, 0.05);
  border-left: 4px solid var(--warm);
}

.limitations-section ul {
  padding-left: 1.5rem;
  margin-top: 0.5rem;
}

.limitations-section li {
  margin-bottom: 0.5rem;
  color: var(--ink);
}

