(function() {
  'use strict';

  // Configuration based on teaching assumptions
  const H = 0.6; // Source Entropy (bits/symbol)
  const R = 1.0; // Max Entropy/Channel Rate (bits/symbol)

  // DOM Elements
  const inputN = document.getElementById('input-n');
  const valN = document.getElementById('val-n');
  const btnReset = document.getElementById('btn-reset');
  const canvas = document.getElementById('typical-chart');
  const ctx = canvas.getContext('2d');

  // Stats Elements
  const statTotal = document.getElementById('stat-total');
  const statTypical = document.getElementById('stat-typical');
  const statProb = document.getElementById('stat-prob');
  const statRatio = document.getElementById('stat-ratio');

  // State
  let currentN = parseInt(inputN.value, 10);

  // Helper: Format large numbers
  function formatNumber(num) {
    if (num > 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num > 1e6) return (num / 1e6).toFixed(2) + 'M';
    if (num > 1e3) return (num / 1e3).toFixed(1) + 'k';
    return Math.round(num).toString();
  }

  // Core Calculation
  function calculateStats(n) {
    const totalSequences = Math.pow(2, R * n);
    const typicalSequences = Math.pow(2, H * n);
    // Probability of typical set approaches 1 as N increases.
    // Using a simplified model for visualization: P(typical) = 1 - (1/2)^(n * (R-H)/2)
    // This is a teaching approximation to show convergence without complex large deviation theory.
    const nonTypicalProb = Math.pow(0.5, n * (R - H) * 0.8); 
    const typicalProb = 1 - nonTypicalProb;
    const ratio = H / R;

    return {
      total: totalSequences,
      typical: typicalSequences,
      prob: typicalProb,
      ratio: ratio
    };
  }

  // Drawing Logic
  function drawChart(stats) {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // We use logarithmic scale for Y axis because numbers grow exponentially
    // Max Y is log2(Total) = R * N
    const maxYLog = R * currentN;

    // Draw Axes
    ctx.beginPath();
    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 2;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // Labels
    ctx.fillStyle = '#1a2b4a';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';

    // Y Axis Labels (Log scale markers)
    ctx.save();
    ctx.translate(padding - 10, canvas.height - padding);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'right';
    ctx.fillText('Log₂(Sequence Count)', 0, 0);
    ctx.restore();

    // Draw Bars
    const barWidth = 60;
    const gap = 40;
    const x1 = padding + 40;
    const x2 = x1 + barWidth + gap;

    // Bar 1: Total Space (Log2 = R*N)
    const h1 = (R * currentN / maxYLog) * chartHeight;
    ctx.fillStyle = '#d1c7b7'; // Muted color for total space
    ctx.fillRect(x1, canvas.height - padding - h1, barWidth, h1);
    ctx.fillText('Total Space', x1 + barWidth/2, canvas.height - padding + 20);
    ctx.fillText(`2^${(R*currentN).toFixed(1)}`, x1 + barWidth/2, canvas.height - padding - h1 - 10);

    // Bar 2: Typical Set (Log2 = H*N)
    const h2 = (H * currentN / maxYLog) * chartHeight;
    ctx.fillStyle = '#007acc'; // Accent color for typical set
    ctx.fillRect(x2, canvas.height - padding - h2, barWidth, h2);
    ctx.fillText('Typical Set', x2 + barWidth/2, canvas.height - padding + 20);
    ctx.fillText(`2^${(H*currentN).toFixed(1)}`, x2 + barWidth/2, canvas.height - padding - h2 - 10);

    // Annotation line for gap
    ctx.beginPath();
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = '#b85c38';
    ctx.moveTo(x1 + barWidth/2, canvas.height - padding - h2);
    ctx.lineTo(x2 + barWidth/2, canvas.height - padding - h2);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = '#b85c38';
    ctx.font = 'italic 12px serif';
    ctx.textAlign = 'left';
    ctx.fillText('Non-typical (Prob → 0)', x2 + barWidth + 10, canvas.height - padding - h2);
  }

  // Update UI
  function update() {
    currentN = parseInt(inputN.value, 10);
    valN.textContent = currentN;

    const stats = calculateStats(currentN);

    statTotal.textContent = formatNumber(stats.total);
    statTypical.textContent = formatNumber(stats.typical);
    statProb.textContent = stats.prob.toFixed(4);
    statRatio.textContent = stats.ratio.toFixed(2);

    drawChart(stats);
  }

  // Event Listeners
  inputN.addEventListener('input', update);

  btnReset.addEventListener('click', function() {
    inputN.value = 10;
    update();
  });

  // Handle reduced motion
  const query = window.matchMedia('(prefers-reduced-motion: reduce)');
  if (query.matches) {
    // Disable animations if any were added later, currently static draw
    console.log('Reduced motion enabled');
  }

  // Initial Draw
  update();

})();
